#include "settlement/SpecialistServiceBridge.hpp"
#include "core/Saturating.hpp"
namespace elysium::settlement {bool SpecialistServiceBridge::add(SpecialistActor a){if(!a.stableId||!a.homeSettlementId||actors_.contains(a.stableId))return false;actors_[a.stableId]=a;return true;}SpecialistFailure SpecialistServiceBridge::assign(std::uint64_t id,std::uint64_t assignment,std::uint64_t population,std::uint64_t capacity){auto i=actors_.find(id);if(i==actors_.end()||!assignment)return SpecialistFailure::Invalid;if(i->second.assignmentStableId&&i->second.assignmentStableId!=assignment)return SpecialistFailure::DuplicateAssignment;if(capacity&&population>=capacity)return SpecialistFailure::RoleCapacity;i->second.assignmentStableId=assignment;i->second.revision=elysium::safe::saturatingIncrement(i->second.revision);return SpecialistFailure::None;}SpecialistServiceResult SpecialistServiceBridge::request(const SpecialistServiceRequest&r,const SpecialistLocalContext&c)const{SpecialistServiceResult o;auto i=actors_.find(r.specialistStableId);if(!r.stableId||i==actors_.end()||!r.targetStableId){o.failure=SpecialistFailure::Invalid;return o;}auto&a=i->second;o.specialistStableId=a.stableId;o.targetStableId=r.targetStableId;o.role=a.role;if(c.settlementStableId!=a.homeSettlementId||!c.localNetworkId){o.failure=SpecialistFailure::NoLocalNetwork;return o;}if(!c.powered){o.failure=SpecialistFailure::NoPower;return o;}if(!c.roomAccess||!c.roomStableId){o.failure=SpecialistFailure::NoRoomAccess;return o;}if((c.inputCapabilityMask&r.requiredInputMask)!=r.requiredInputMask){o.failure=SpecialistFailure::MissingInput;return o;}o.accepted=true;return o;}FutureJobAdapter SpecialistServiceBridge::jobAdapter(std::uint64_t id)const{auto i=actors_.find(id);if(i==actors_.end())return {};return {i->second.stableId,i->second.assignmentStableId,1ULL<<static_cast<unsigned>(i->second.role)};}const SpecialistActor*SpecialistServiceBridge::find(std::uint64_t id)const{auto i=actors_.find(id);return i==actors_.end()?nullptr:&i->second;}}
